61	  private MutableRate merkleTreeCreateLatencyNS;
62	
63	  public void incrementMerkleTreeWriteFailures() {
64	    this.numMerkleTreeWriteFailure.incr();
65	  }
66	
67	  public void incrementMerkleTreeReadFailures() {
68	    this.numMerkleTreeReadFailure.incr();
