73	  }
74	
75	  public MutableRate getReadContainerMerkleTreeLatencyNS() {
76	    return this.merkleTreeReadLatencyNS;
77	  }
78	
79	  public MutableRate getCreateMerkleTreeLatencyNS() {
80	    return this.merkleTreeCreateLatencyNS;
81	  }
