26	import java.util.SortedMap;
27	import java.util.TreeMap;
28	
29	/**
30	 * This class represents a Merkle tree that provides one checksum for all data within a container.
31	 *
32	 * As the leaves of the tree, a checksum for each chunk is computed by taking a checksum of all checksums within that
33	 * chunk. Each chunk checksum in a block is further checksummed together to generate the block level checksum. Finally,
34	 * The checksums of all blocks are checksummed together to create a container level checksum.
35	 * Note that checksums are order dependent. Chunk checksums are sorted by their
36	 * offset within a block, and block checksums are sorted by their block ID.
37	 *
38	 * This class can be used to construct a consistent and completely filled {@link ContainerProtos.ContainerMerkleTree}
39	 * object. It allows building a container merkle tree from scratch by incrementally adding chunks.
40	 * The final checksums at higher levels of the tree are not calculated until
41	 * {@link ContainerMerkleTree#toProto} is called.
42	 */
43	public class ContainerMerkleTree {
44	
45	  private final SortedMap<Long, BlockMerkleTree> id2Block;
46	
47	  /**
48	   * Constructs an empty Container merkle tree object.
49	   */
50	  public ContainerMerkleTree() {
51	    id2Block = new TreeMap<>();
52	  }
53	
54	  /**
55	   * Adds chunks to a block in the tree. The block entry will be created if it is the first time adding chunks to it.
56	   * If the block entry already exists, the chunks will be added to the existing chunks for that block.
57	   *
58	   * @param blockID The ID of the block that these chunks belong to.
59	   * @param chunks A list of chunks to add to this block. The chunks will be sorted internally by their offset.
60	   */
61	  public void addChunks(long blockID, Collection<ContainerProtos.ChunkInfo> chunks) {
62	    id2Block.computeIfAbsent(blockID, BlockMerkleTree::new).addChunks(chunks);
63	  }
64	
65	  /**
66	   * Uses chunk hashes to compute all remaining hashes in the tree, and returns it as a protobuf object. No checksum
67	   * computation for the tree happens outside of this method.
68	   *
69	   * @return A complete protobuf object representation of this tree.
70	   */
71	  public ContainerProtos.ContainerMerkleTree toProto() {
72	    // Compute checksums and return the result.
73	    ContainerProtos.ContainerMerkleTree.Builder containerTreeBuilder = ContainerProtos.ContainerMerkleTree.newBuilder();
74	    ChecksumByteBuffer checksumImpl = ChecksumByteBufferFactory.crc32Impl();
75	    ByteBuffer containerChecksumBuffer = ByteBuffer.allocate(Long.BYTES * id2Block.size());
76	
77	    for (BlockMerkleTree blockTree: id2Block.values()) {
78	      ContainerProtos.BlockMerkleTree blockTreeProto = blockTree.toProto();
79	      containerTreeBuilder.addBlockMerkleTree(blockTreeProto);
80	      // Add the block's checksum to the buffer that will be used to calculate the container checksum.
81	      containerChecksumBuffer.putLong(blockTreeProto.getBlockChecksum());
82	    }
83	    containerChecksumBuffer.flip();
84	    checksumImpl.update(containerChecksumBuffer);
85	
86	    return containerTreeBuilder
87	        .setDataChecksum(checksumImpl.getValue())
88	        .build();
89	  }
90	
91	  /**
92	   * Represents a merkle tree for a single block within a container.
93	   */
94	  private static class BlockMerkleTree {
95	    // Map of each offset within the block to its chunk info.
96	    // Chunk order in the checksum is determined by their offset.
97	    private final SortedMap<Long, ChunkMerkleTree> offset2Chunk;
98	    private final long blockID;
99	
100	    BlockMerkleTree(long blockID) {
101	      this.blockID = blockID;
102	      this.offset2Chunk = new TreeMap<>();
103	    }
104	
105	    /**
106	     * Adds the specified chunks to this block. The offset value of the chunk must be unique within the block,
107	     * otherwise it will overwrite the previous value at that offset.
108	     *
109	     * @param chunks A list of chunks to add to this block.
110	     */
111	    public void addChunks(Collection<ContainerProtos.ChunkInfo> chunks) {
112	      for (ContainerProtos.ChunkInfo chunk: chunks) {
113	        offset2Chunk.put(chunk.getOffset(), new ChunkMerkleTree(chunk));
114	      }
115	    }
116	
117	    /**
118	     * Uses chunk hashes to compute a block hash for this tree, and returns it as a protobuf object. All block checksum
119	     * computation for the tree happens within this method.
120	     *
121	     * @return A complete protobuf object representation of this block tree.
122	     */
123	    public ContainerProtos.BlockMerkleTree toProto() {
124	      ContainerProtos.BlockMerkleTree.Builder blockTreeBuilder = ContainerProtos.BlockMerkleTree.newBuilder();
125	      ChecksumByteBuffer checksumImpl = ChecksumByteBufferFactory.crc32Impl();
126	      ByteBuffer blockChecksumBuffer = ByteBuffer.allocate(Long.BYTES * offset2Chunk.size());
127	
128	      for (ChunkMerkleTree chunkTree: offset2Chunk.values()) {
129	        // Ordering of checksums within a chunk is assumed to be in the order they are written.
130	        // This assumption is already built in to the code that reads and writes the values (see
131	        // ChunkInputStream#validateChunk for an example on the client read path).
132	        // There is no other value we can use to sort these checksums, so we assume the stored proto has them in the
133	        // correct order.
134	        ContainerProtos.ChunkMerkleTree chunkTreeProto = chunkTree.toProto();
135	        blockTreeBuilder.addChunkMerkleTree(chunkTreeProto);
136	        blockChecksumBuffer.putLong(chunkTreeProto.getChunkChecksum());
137	      }
138	      blockChecksumBuffer.flip();
139	      checksumImpl.update(blockChecksumBuffer);
140	
141	      return blockTreeBuilder
142	          .setBlockID(blockID)
143	          .setBlockChecksum(checksumImpl.getValue())
144	          .build();
145	    }
146	  }
147	
