51	
52	    long prevBlockID = -1;
53	    for (int blockIndex = 0; blockIndex < expectedTree.getBlockMerkleTreeCount(); blockIndex++) {
54	      ContainerProtos.BlockMerkleTree expectedBlockTree = expectedTree.getBlockMerkleTree(blockIndex);
55	      ContainerProtos.BlockMerkleTree actualBlockTree = actualTree.getBlockMerkleTree(blockIndex);
56	
57	      // Blocks should be sorted by block ID.
58	      long currentBlockID = actualBlockTree.getBlockID();
59	      assertTrue(prevBlockID < currentBlockID);
60	      prevBlockID = currentBlockID;
61	
62	      assertEquals(expectedBlockTree.getBlockID(), actualBlockTree.getBlockID());
63	      assertEquals(expectedBlockTree.getBlockChecksum(), actualBlockTree.getBlockChecksum());
64	
65	      long prevChunkOffset = -1;
