              ContainerProtos.Result.IO_EXCEPTION);
        }

        ContainerProtos.ContainerChecksumInfo thisChecksumInfoProto = thisChecksumInfo.get().build();
        if (thisChecksumInfoProto.getContainerID() != peerChecksumInfo.getContainerID()) {
          throw new StorageContainerException("Container ID does not match. Local container ID "
              + thisChecksumInfoProto.getContainerID() + " , Peer container ID " + peerChecksumInfo.getContainerID(),
              ContainerProtos.Result.CONTAINER_ID_MISMATCH);
        }

        compareContainerMerkleTree(thisChecksumInfoProto, peerChecksumInfo, report);
