    } catch (StorageContainerException ex) {
      metrics.incrementMerkleTreeDiffFailures();
      throw ex;
    } catch (IOException ex) {
      metrics.incrementMerkleTreeDiffFailures();
      throw new StorageContainerException("Container Diff failed for container #" + thisContainer.getContainerID(),
          ex, ContainerProtos.Result.IO_EXCEPTION);
    }

    // Update the metrics based on the diff result.
    if (report.needsRepair()) {
      metrics.incrementRepairContainerDiffs();
    } else {
      metrics.incrementNoRepairContainerDiffs();
